        {
          "headline": "Apple tells developers it will restrict macOS Full Disk Access, citing the growing risk from AI agents",
          "sources": [
            { "name": "Apple", "url": "https://developer.apple.com/news/?id=p6zjojqw" },
            { "name": "TechCrunch", "url": "https://techcrunch.com/2026/10/02/apple-says-its-tightening-macos-full-disk-access-controls-due-to-new-risks-from-ai-agents/" },
            { "name": "MacRumors", "url": "https://www.macrumors.com/2026/10/02/apple-announces-macos-full-disk-access-changes/" }
